tool_input.new_string:
const submit = page.locator('.login-submit')
const roleSubmit = page.getByRole('button', { name: '登录', exact: true })
const textSubmit = page.getByText('登录', { exact: true }).last()
const submitCount = await submit.count()
const roleSubmitCount = await roleSubmit.count()
const textSubmitCount = await textSubmit.count()
if (!submitCount && !roleSubmitCount && !textSubmitCount) {
  const controls = await page.evaluate(() => [...document.querySelectorAll('body *')]
    .filter(item => item.children.length === 0 && item.textContent?.trim() === '登录')
    .map(item => ({ tag: item.tagName, className: item.className, role: item.getAttribute('role') })))
  throw new Error(`Login submit control missing: ${JSON.stringify({ inputDetails, controls })}`)
}
const submitTarget = submitCount ? submit.first() : roleSubmitCount ? roleSubmit : textSubmit
await submitTarget.click({ timeout: 5000 })
